import{c as e,Q as o,j as n,m as s}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Anthropic 如何搭建 Production AI Agents（Claude Managed Agents 完整教學）","description":"","frontmatter":{"url":"https://x.com/Mikocrypto11/status/2060346922205052929","title":"Anthropic 如何搭建 Production AI Agents（Claude Managed Agents 完整教學）","author":"@0x_Miko（Mikocrypto11）","archived":"2026-05-31T00:00:00.000Z","handle":"@Mikocrypto11","published":"2026-05-29T00:00:00.000Z","type":"tweet"},"headers":[],"relativePath":"research/tweets/2026-05-29-@Mikocrypto11-2060346922205052929.md","filePath":"research/tweets/2026-05-29-@Mikocrypto11-2060346922205052929.md","lastUpdated":1780990164000}'),r={name:"research/tweets/2026-05-29-@Mikocrypto11-2060346922205052929.md"};function a(i,t,g,p,l,d){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="anthropic-如何搭建-production-ai-agents-claude-managed-agents-完整教學-—-0x-miko" tabindex="-1">Anthropic 如何搭建 Production AI Agents（Claude Managed Agents 完整教學）— @0x_Miko <a class="header-anchor" href="#anthropic-如何搭建-production-ai-agents-claude-managed-agents-完整教學-—-0x-miko" aria-label="Permalink to &quot;Anthropic 如何搭建 Production AI Agents（Claude Managed Agents 完整教學）— @0x_Miko&quot;">​</a></h1><p><strong>來源</strong>: <a href="https://x.com/Mikocrypto11/status/2060346922205052929" target="_blank" rel="noreferrer">https://x.com/Mikocrypto11/status/2060346922205052929</a><strong>作者</strong>: @0x_Miko（Mikocrypto11） <strong>發布日期</strong>: 2026-05-29 <strong>收錄日期</strong>: 2026-05-31 <strong>時長</strong>: 37:08 <strong>原始語言</strong>: 英文 <strong>演講者</strong>: Isabella He（Anthropic Applied AI Team, Member of Technical Staff） <strong>備注</strong>: 轉錄模型 faster-whisper small（CPU）；「Quad」= Whisper 誤辨識的「Claude」</p><hr><h2 id="核心摘要" tabindex="-1">核心摘要 <a class="header-anchor" href="#核心摘要" aria-label="Permalink to &quot;核心摘要&quot;">​</a></h2><blockquote><p>Anthropic Applied AI 工程師 Isabella He 親授如何將 Claude Managed Agents 從 demo 推進到 production，37 分鐘 hands-on workshop，示範搭建一個 incident response（site reliability）agent。</p></blockquote><h3 id="_1-演進脈絡" tabindex="-1">1. 演進脈絡 <a class="header-anchor" href="#_1-演進脈絡" aria-label="Permalink to &quot;1. 演進脈絡&quot;">​</a></h3><table tabindex="0"><thead><tr><th>階段</th><th>時間</th><th>說明</th></tr></thead><tbody><tr><td>Messages API</td><td>2023</td><td>純 tokens in/out，所有 agent primitives 自行實作</td></tr><tr><td>Claude Code Tools</td><td>~2024</td><td>Sandboxed tool execution，讓工具在容器內安全運行</td></tr><tr><td>Claude Managed Agents</td><td>現在</td><td>Purpose-built harness，production-ready，開發速度快 10–15×</td></tr></tbody></table><h3 id="_2-核心架構-brains-腦-與-hands-手-分離" tabindex="-1">2. 核心架構：Brains（腦）與 Hands（手）分離 <a class="header-anchor" href="#_2-核心架構-brains-腦-與-hands-手-分離" aria-label="Permalink to &quot;2. 核心架構：Brains（腦）與 Hands（手）分離&quot;">​</a></h3><ul><li><strong>Brains（Server-side）</strong>：agent definition、context management、compaction、prompt caching、observability console</li><li><strong>Hands（Client-side）</strong>：local tool execution，在用戶自己的基礎設施上執行，credentials 存在 Vaults 中</li></ul><p>這個分離確保憑證安全性，開發者不需自建 secret store。</p><h3 id="_3-五大-primitives" tabindex="-1">3. 五大 Primitives <a class="header-anchor" href="#_3-五大-primitives" aria-label="Permalink to &quot;3. 五大 Primitives&quot;">​</a></h3><ol><li><strong>Agent Definition</strong>：persona、capabilities、系統提示（server 端定義）</li><li><strong>Environments</strong>：agent 可使用的 data、context、tool 清單</li><li><strong>Sessions</strong>：Agent definition + Environment 組合，產生 conversation thread</li><li><strong>Local Tools</strong>：<code>get_metrics</code>、<code>get_recent_deploys</code>、<code>get_diffs</code> 等，agent 在 session 中呼叫</li><li><strong>Streaming</strong>：Sessions 以 <strong>events</strong> 為單位回傳（非 tokens in/out），支援即時串流 + observability logging</li></ol><h3 id="_4-sessions-以-events-運作-關鍵差異" tabindex="-1">4. Sessions 以 Events 運作（關鍵差異） <a class="header-anchor" href="#_4-sessions-以-events-運作-關鍵差異" aria-label="Permalink to &quot;4. Sessions 以 Events 運作（關鍵差異）&quot;">​</a></h3><p>傳統 Messages API 是 request/response（tokens in → tokens out）。<br> Claude Managed Agents 中，一個 session 內所有互動都是 <strong>events 追加到 log</strong>：</p><ul><li><code>user.message</code>、<code>agent.tool_call</code>、<code>agent.response</code> 等</li><li>每個 event 可即時 stream 給前端用戶</li><li>同時作為 observability 記錄，可在 console 查看 agent 完整行為</li></ul><h3 id="_5-context-anxiety-案例" tabindex="-1">5. Context Anxiety 案例 <a class="header-anchor" href="#_5-context-anxiety-案例" aria-label="Permalink to &quot;5. Context Anxiety 案例&quot;">​</a></h3><p>Sonnet 4.5 出現「context anxiety」問題：context window 還有空間時就提前結束任務。<br> 團隊在 harness 中加入緩解機制 → 但 Opus 4.5 發布後此行為消失 → harness 中的修補變成廢棄代碼。<br><strong>教訓</strong>：harness 必須與模型一起演進，這是選擇 managed harness 的原因之一。</p><h3 id="_6-進階功能-beyond-the-basics" tabindex="-1">6. 進階功能（Beyond the Basics） <a class="header-anchor" href="#_6-進階功能-beyond-the-basics" aria-label="Permalink to &quot;6. 進階功能（Beyond the Basics）&quot;">​</a></h3><ul><li><strong>Dreaming</strong>：self-improving agents + memory（下一個 session 主題）</li><li><strong>Webhooks</strong>：讓 agent 響應外部事件觸發</li><li><strong>Fine-grained permission policies</strong>：細粒度工具執行權限</li><li><strong>MCP Server controls</strong>：新發布的 MCP server 管理功能</li><li><strong>Console Agent Builder</strong>：Anthropic console 內建 observability dashboard + 視覺化 agent 定義介面</li><li><strong>Credential Vaults</strong>：built-in secret store，無需自建</li></ul><h3 id="_7-demo-重點" tabindex="-1">7. Demo 重點 <a class="header-anchor" href="#_7-demo-重點" aria-label="Permalink to &quot;7. Demo 重點&quot;">​</a></h3><ul><li>Framework：Streamlit + Python</li><li>Use case：Incident Response Agent（SRE agent）</li><li>工具：<code>get_metrics</code>、<code>get_recent_deploys</code>、<code>get_diffs</code></li><li>流程：Clone repo → <code>.env</code> 填入 Anthropic API key → <code>streamlit run app.py</code></li><li>Agent 回應 3AM oncall 場景，自動分析 metrics、diff、deploy 記錄</li></ul><hr><h2 id="逐字稿-含時間戳" tabindex="-1">逐字稿（含時間戳） <a class="header-anchor" href="#逐字稿-含時間戳" aria-label="Permalink to &quot;逐字稿（含時間戳）&quot;">​</a></h2><blockquote><p>⚠️ Whisper small 模型誤辨識：<code>Quad</code> = <code>Claude</code>，<code>Quad Code</code> = <code>Claude Code</code></p></blockquote><p><strong>[00:19 → 00:21]</strong> All right, hello, everyone.</p><p><strong>[00:21 → 00:23]</strong> It&#39;s great to see you all here today for our session</p><p><strong>[00:23 → 00:25]</strong> on shipping your first managed agent.</p><p><strong>[00:25 → 00:27]</strong> Let&#39;s go ahead and get started.</p><p><strong>[00:27 → 00:28]</strong> My name is Isabella He.</p><p><strong>[00:28 → 00:31]</strong> I&#39;m a member of technical staff at Anthropic</p><p><strong>[00:31 → 00:32]</strong> on the Applied AI team.</p><p><strong>[00:32 → 00:35]</strong> The Applied AI team at Anthropic sits at the intersection</p><p><strong>[00:35 → 00:37]</strong> of products, research, and our customers,</p><p><strong>[00:37 → 00:39]</strong> which means that I get to contribute internally</p><p><strong>[00:39 → 00:41]</strong> to products at Anthropic, like Claude Code</p><p><strong>[00:41 → 00:43]</strong> and our Claude Harnesses,</p><p><strong>[00:43 → 00:45]</strong> as well as work externally with our customers</p><p><strong>[00:45 → 00:47]</strong> that are building on top of Claude</p><p><strong>[00:47 → 00:48]</strong> and on top of our Harnesses.</p><p><strong>[00:48 → 00:51]</strong> So my goal today is to get you all hands on</p><p><strong>[00:51 → 00:53]</strong> with actually building on top of managed agents,</p><p><strong>[00:53 → 00:56]</strong> understanding how the harness works under the hood,</p><p><strong>[00:56 → 00:57]</strong> and getting you ready to actually ship</p><p><strong>[00:57 → 01:00]</strong> your first incident response management.</p><p><strong>[01:00 → 01:02]</strong> So as a quick overview of today&#39;s agenda,</p><p><strong>[01:02 → 01:04]</strong> we&#39;re gonna cover first a quick refresher</p><p><strong>[01:04 → 01:06]</strong> of Claude managed agents.</p><p><strong>[01:06 → 01:07]</strong> I wanna talk you through a little bit</p><p><strong>[01:07 → 01:09]</strong> about how this harness works under the hood</p><p><strong>[01:09 → 01:11]</strong> and what makes it so special.</p><p><strong>[01:11 → 01:12]</strong> Our team put a lot of thought</p><p><strong>[01:12 → 01:15]</strong> into the architectural design of Claude managed agents</p><p><strong>[01:15 → 01:17]</strong> to make sure that it runs ready and reliably</p><p><strong>[01:17 → 01:19]</strong> for production-ready agents.</p><p><strong>[01:19 → 01:20]</strong> So I wanna talk you through a little bit</p><p><strong>[01:20 → 01:21]</strong> of how that works,</p><p><strong>[01:21 → 01:23]</strong> so that then when we transition</p><p><strong>[01:23 → 01:24]</strong> into the second portion here,</p><p><strong>[01:24 → 01:26]</strong> which is the hands-on workshop,</p><p><strong>[01:26 → 01:28]</strong> you&#39;ll actually understand what each of the primitives</p><p><strong>[01:28 → 01:30]</strong> you&#39;re building actually mean</p><p><strong>[01:30 → 01:32]</strong> for your agents under the hood.</p><p><strong>[01:32 → 01:33]</strong> So for the majority of today&#39;s session,</p><p><strong>[01:33 → 01:36]</strong> I want you all to actually have your laptops open,</p><p><strong>[01:36 → 01:37]</strong> building alongside me,</p><p><strong>[01:37 → 01:39]</strong> actually working inside of a repository,</p><p><strong>[01:39 → 01:41]</strong> and getting you ready to actually spin up</p><p><strong>[01:41 → 01:44]</strong> a working incident response agent.</p><p><strong>[01:44 → 01:45]</strong> Lastly, we&#39;ll talk a little bit</p><p><strong>[01:45 → 01:47]</strong> about Beyond the Basics.</p><p><strong>[01:47 → 01:48]</strong> Today&#39;s session is the first session</p><p><strong>[01:48 → 01:49]</strong> of a couple of other ones</p><p><strong>[01:49 → 01:50]</strong> that we&#39;ll build on top of this</p><p><strong>[01:50 → 01:52]</strong> on Claude managed agents.</p><p><strong>[01:52 → 01:53]</strong> Specifically right after this one,</p><p><strong>[01:53 → 01:55]</strong> I think there&#39;s another session on Dreaming,</p><p><strong>[01:55 → 01:57]</strong> which is one of my favorite new features</p><p><strong>[01:57 → 01:58]</strong> with Claude managed agents</p><p><strong>[01:58 → 01:59]</strong> for self-improving agents</p><p><strong>[01:59 → 02:01]</strong> and memory built into the harness.</p><p><strong>[02:01 → 02:04]</strong> So encourage everyone to dive in a little bit deeper</p><p><strong>[02:04 → 02:06]</strong> into what else is in the box</p><p><strong>[02:06 → 02:07]</strong> after we set you all up for success today</p><p><strong>[02:07 → 02:09]</strong> with a quick introduction.</p><p><strong>[02:10 → 02:11]</strong> So let&#39;s first touch a little bit</p><p><strong>[02:11 → 02:14]</strong> about how we got here with Claude managed agents.</p><p><strong>[02:14 → 02:18]</strong> When we first released the very first Claude back in 2023,</p><p><strong>[02:18 → 02:22]</strong> we released the messages API alongside access to Claude.</p><p><strong>[02:22 → 02:26]</strong> This provided raw model access to all Claude models.</p><p><strong>[02:26 → 02:27]</strong> This became the very first way</p><p><strong>[02:27 → 02:30]</strong> that people could programmatically build on top of Claude</p><p><strong>[02:30 → 02:32]</strong> and essentially gave a way</p><p><strong>[02:32 → 02:34]</strong> for people to access tokens in and tokens out</p><p><strong>[02:34 → 02:36]</strong> via our Claude models.</p><p><strong>[02:36 → 02:38]</strong> This also meant that for everyone building</p><p><strong>[02:38 → 02:40]</strong> on top of Claude models,</p><p><strong>[02:40 → 02:42]</strong> they had to implement all the various primitives themselves,</p><p><strong>[02:42 → 02:44]</strong> things like context management,</p><p><strong>[02:44 → 02:47]</strong> the actual agent loop, compaction, et cetera,</p><p><strong>[02:47 → 02:50]</strong> all the primitives that come alongside making an agent work.</p><p><strong>[02:50 → 02:52]</strong> When models were less intelligent</p><p><strong>[02:52 → 02:55]</strong> back in the early days of let&#39;s say 2023,</p><p><strong>[02:55 → 02:56]</strong> some of these primitives were much simpler</p><p><strong>[02:56 → 02:59]</strong> and much easier to implement by developers.</p><p><strong>[02:59 → 03:02]</strong> But as models have gotten more and more intelligent,</p><p><strong>[03:02 → 03:04]</strong> and agents have gotten more and more complex,</p><p><strong>[03:04 → 03:07]</strong> these primitives have gotten harder and harder to implement</p><p><strong>[03:07 → 03:09]</strong> and maintain inside of your own harnesses.</p><p><strong>[03:09 → 03:11]</strong> That&#39;s why Anthropic started releasing</p><p><strong>[03:11 → 03:14]</strong> some of these things like Claude Code as the first step here</p><p><strong>[03:14 → 03:17]</strong> where Claude Code was able to come in</p><p><strong>[03:17 → 03:19]</strong> and run a sandboxed tool execution environment</p><p><strong>[03:19 → 03:22]</strong> allowing Claude to take actions locally</p><p><strong>[03:22 → 03:25]</strong> and safely run code, call tools and programs</p><p><strong>[03:25 → 03:28]</strong> that developers were comfortable running,</p><p><strong>[03:28 → 03:30]</strong> and that were safe to run within their containers.</p><p><strong>[03:30 → 03:33]</strong> That&#39;s only then evolved into Claude managed agents,</p><p><strong>[03:33 → 03:36]</strong> which is the first harness to be able to handle</p><p><strong>[03:36 → 03:38]</strong> scaling and production-ready components</p><p><strong>[03:38 → 03:39]</strong> for you by Anthropic,</p><p><strong>[03:39 → 03:42]</strong> providing things like a purpose-built harness,</p><p><strong>[03:42 → 03:45]</strong> sandboxing, observability, tool runtime,</p><p><strong>[03:45 → 03:48]</strong> all within a managed infrastructure system.</p><p><strong>[03:48 → 03:50]</strong> This means that developers can focus on task</p><p><strong>[03:50 → 03:53]</strong> and agent configuration, custom tool logic,</p><p><strong>[03:53 → 03:55]</strong> the things that actually matter</p><p><strong>[03:55 → 03:56]</strong> for bringing domain expertise</p><p><strong>[03:56 → 03:58]</strong> and customized ability to your agents,</p><p><strong>[03:58 → 04:01]</strong> where you&#39;re handing off the rest of all the primitives</p><p><strong>[04:01 → 04:03]</strong> and core compute and primitives</p><p><strong>[04:03 → 04:06]</strong> of essentially managing the basics of agent running</p><p><strong>[04:06 → 04:09]</strong> to Anthropic.</p><p><strong>[04:09 → 04:12]</strong> So that brings me to managed agents as the fastest way</p><p><strong>[04:12 → 04:15]</strong> to build production-ready agents on Claude.</p><p><strong>[04:15 → 04:17]</strong> We&#39;ve seen people build 10 to 15 times faster</p><p><strong>[04:17 → 04:19]</strong> to production with Claude managed agents</p><p><strong>[04:19 → 04:22]</strong> by leveraging our purpose-built harness.</p><p><strong>[04:22 → 04:24]</strong> Part of the reason why we built Claude managed agents</p><p><strong>[04:24 → 04:29]</strong> is because harnesses should evolve alongside your agents.</p><p><strong>[04:29 → 04:31]</strong> For example, back when we were building ourselves</p><p><strong>[04:31 → 04:34]</strong> on top of models like Sonnet 4.5,</p><p><strong>[04:34 → 04:36]</strong> we noticed that Sonnet 4.5 emitted</p><p><strong>[04:36 → 04:38]</strong> a particular behavior called context anxiety.</p><p><strong>[04:38 → 04:40]</strong> This meant that with Sonnet 4.5,</p><p><strong>[04:40 → 04:42]</strong> Claude started wrapping up tasks early,</p><p><strong>[04:42 → 04:43]</strong> even when it still had a room to spare</p><p><strong>[04:43 → 04:45]</strong> in its context window.</p><p><strong>[04:45 → 04:47]</strong> To manage that in our harness,</p><p><strong>[04:47 → 04:49]</strong> we then added some mitigations</p><p><strong>[04:49 → 04:52]</strong> to combat against this early stopping behavior.</p><p><strong>[04:52 → 04:54]</strong> But when Opus 4.5 then came out,</p><p><strong>[04:54 → 04:56]</strong> we actually saw this behavior go away.</p><p><strong>[04:56 → 04:58]</strong> Making all that work we had done inside of the harness</p><p><strong>[04:58 → 05:01]</strong> essentially obsolete because Claude had evolved</p><p><strong>[05:01 → 05:02]</strong> beyond that behavior that we had built</p><p><strong>[05:02 → 05:04]</strong> into the harness to manage.</p><p><strong>[05:04 → 05:07]</strong> So the takeaway there is that it&#39;s a lot of work</p><p><strong>[05:07 → 05:08]</strong> to maintain harnesses and make sure</p><p><strong>[05:08 → 05:11]</strong> that they actually evolve alongside your agents,</p><p><strong>[05:11 → 05:13]</strong> which is why with Claude managed agents,</p><p><strong>[05:13 → 05:15]</strong> we want to make it really easy for Claude</p><p><strong>[05:15 → 05:17]</strong> and Anthropic to handle all the complexities</p><p><strong>[05:17 → 05:18]</strong> that come with compaction,</p><p><strong>[05:18 → 05:21]</strong> caching, things like context anxiety,</p><p><strong>[05:21 → 05:22]</strong> all these various primitives that come</p><p><strong>[05:22 → 05:25]</strong> alongside building an agent that runs in production.</p><hr><p><em>[完整逐字稿詳見原始 transcript，共 982 段落，以下為精選關鍵段落]</em></p><p><strong>[07:00 → 07:10]</strong> <em>(架構說明：Brains vs Hands)</em> The agent itself, the brains, lives on Anthropic&#39;s servers. The hands of the agent, where tools actually get executed, live locally on your infrastructure or wherever you run your agent executor.</p><p><strong>[17:22 → 17:30]</strong> <em>(Sessions 以 events 運作)</em> When our Claude managed agents runs within a single session, instead of responding in tokens in and tokens out, it actually works in units of events. Events here are things like user messages or agent tool calls, agent responses, so that every event can be logged from an observability perspective as well as streamed back to the user.</p><p><strong>[27:18 → 27:57]</strong> <em>(Workshop 總結)</em> We started with an empty agent, built on a couple of primitives on Claude managed agents. We then defined the agent definition, the persona, the capabilities. We gave the agent an environment. We gave the agent data and context to operate over. We then gave the agent sessions combining the agent definitions to an environment so the agent can think through which tools to call. And then it can actually call those tools and take action on our behalf. We then came in and streamed the responses to the user into our logs, implemented some local tools as well as the ability to delete sessions.</p><p><strong>[35:24 → 35:42]</strong> <em>(Credential Vaults)</em> The brains and the hands of the agent are separated so that credentials can be stored very securely in these Vaults. This means that you don&#39;t have to set up your own secret stores or your own credential stores and you can just rely on the built-in capability here.</p><p><strong>[36:20 → 36:47]</strong> <em>(結語)</em> Hopefully everyone leaves here with a bit of a mental model about how managed agents actually works under the hood... you were able to come in and save future developers hours of time being woken up at 3 a.m. or 2 a.m. in the morning and being able to handle incidents for them.</p><hr><p><em>逐字稿轉錄：faster-whisper small，CPU，2026-05-31。982 段落，完整原始 JSON 存於 <code>/tmp/claude-scratch/media-transcribe/transcript_raw.json</code>（session 結束後清除）。</em></p>',175)])])}const u=e(r,[["render",a]]);export{c as __pageData,u as default};
